// Language of the page, site root and translated texts for the scripts that draw content (roadmap, changelog,
// configurator, add-ons). English and German pages carry both languages side by side; the pages of the other
// languages (/es/, /fr/, /pt-br/, /pl/, /ru/, generated by tools/i18n/build-i18n.mjs) carry one, name it in
// <meta name="pw-lang"> and the way back to the site root in <meta name="pw-root">.
//
//   import { root, load, text, spans, href } from '../i18n.js';
//   const data = await fetch(root('assets/data/roadmap.json')).then((r) => r.json());
//   await load();                       // the texts of a translated page (assets/i18n/<lang>.json), no-op on EN/DE
//   title.append(spans(item.title));    // <span lang="en">…</span><span lang="de">…</span>, or one <span lang="fr">
//   link.href = href(item.link.href);   // a link written for the English/German page, right for this page

export const OFFICIAL = Object.freeze(['en', 'de']);
export const EXTRA = Object.freeze(['es', 'fr', 'pt-br', 'pl', 'ru']);
export const LOCALES = Object.freeze({ en: 'en', de: 'de', es: 'es', fr: 'fr', 'pt-br': 'pt-BR', pl: 'pl', ru: 'ru' });

const SITE_ROOT = new URL('../../', import.meta.url).href;

/** The dictionary key of an English text: whitespace collapsed, markup kept. */
export function normalize(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

/** Replaces {name} placeholders with values (missing ones stay as they are). */
export function fill(template, values) {
  if (!values) return String(template);
  return String(template).replace(/\{(\w+)\}/g, (m, key) => (Object.prototype.hasOwnProperty.call(values, key) ? String(values[key]) : m));
}

/**
 * One language context. The module's own functions below use the context of the current document; tests and
 * tools build their own: createI18n({ lang: 'fr', root: 'https://example.org/', base: '…', texts, pages }).
 */
export function createI18n(env = {}) {
  const doc = env.document !== undefined ? env.document : (typeof document === 'undefined' ? null : document);
  const meta = (name) => {
    const el = doc && doc.querySelector ? doc.querySelector(`meta[name="${name}"]`) : null;
    return el ? el.getAttribute('content') : null;
  };
  const base = env.base || (doc && doc.baseURI) || SITE_ROOT;
  const rootUrl = new URL(env.root || meta('pw-root') || SITE_ROOT, base).href;
  const declared = env.lang !== undefined ? env.lang : meta('pw-lang');
  const extra = EXTRA.includes(declared) ? declared : null;
  let texts = env.texts ? new Map(Object.entries(env.texts).map(([k, v]) => [normalize(k), v])) : null;
  let pages = env.pages ? [...env.pages] : null;
  let pending = null;
  const missing = new Set();

  function lang() {
    if (extra) return extra;
    return doc && doc.documentElement && doc.documentElement.lang === 'de' ? 'de' : 'en';
  }

  function root(path = '') {
    return new URL(path, rootUrl).href;
  }

  function load() {
    if (!extra || texts) return Promise.resolve(api);
    if (!pending) {
      const get = env.fetch || ((url, init) => fetch(url, init));
      pending = Promise.resolve()
        .then(() => get(root(`assets/i18n/${extra}.json`), { credentials: 'same-origin' }))
        .then((res) => {
          if (!res.ok) throw new Error(`i18n: HTTP ${res.status}`);
          return res.json();
        })
        .then((data) => {
          texts = new Map(Object.entries((data && data.texts) || {}));
          pages = Array.isArray(data && data.pages) ? data.pages : [];
          return api;
        }, (err) => {
          texts = new Map();
          pages = [];
          api.error = err;
          return api;
        });
    }
    return pending;
  }

  function lookup(en) {
    if (!extra) return en;
    const key = normalize(en);
    if (texts && texts.has(key)) return texts.get(key);
    if (key) missing.add(key);
    return en;
  }

  function text(value, values) {
    if (value == null) return '';
    if (typeof value === 'string') return fill(lookup(value), values);
    if (extra) return fill(lookup(value.en ?? ''), values);
    const l = lang();
    return fill(value[l] ?? value.en ?? '', values);
  }

  function spans(value, values) {
    const frag = doc.createDocumentFragment();
    const span = (l, content) => {
      const el = doc.createElement('span');
      el.setAttribute('lang', l);
      el.textContent = content;
      frag.appendChild(el);
    };
    if (value == null) return frag;
    if (extra) {
      span(extra, text(value, values));
      return frag;
    }
    if (typeof value === 'string') {
      frag.appendChild(doc.createTextNode(fill(value, values)));
      return frag;
    }
    for (const l of OFFICIAL) span(l, fill(value[l] ?? value.en ?? '', values));
    return frag;
  }

  function href(target) {
    if (!extra || typeof target !== 'string') return target;
    if (/^(?:[a-z][a-z0-9+.-]*:|\/\/|#)/i.test(target) || target === '') return target;
    const tree = new URL(`${extra}/`, rootUrl);
    const url = new URL(target, base);
    if (url.origin !== tree.origin || !url.pathname.startsWith(tree.pathname)) return target;
    const rest = url.pathname.slice(tree.pathname.length);
    const page = rest.replace(/index\.html$/, '');
    if (!/[?&]lang=(?:en|de)(?:&|$)/.test(url.search) && (pages || []).includes(page)) return target;
    return new URL(rest + url.search + url.hash, rootUrl).href;
  }

  function locale(l = lang()) {
    return LOCALES[l] || 'en';
  }

  function number(value, options) {
    return new Intl.NumberFormat(locale(), options).format(value);
  }

  const api = {
    lang, root, load, lookup, text, spans, href, locale, number, fill, normalize,
    translated: () => !!extra,
    has: (en) => !extra || !!(texts && texts.has(normalize(en))),
    missing: () => [...missing],
    error: null,
  };
  return api;
}

let current = null;
const ctx = () => current || (current = createI18n());

/** Language of the page: 'en' or 'de' on the English/German pages (follows the switch), else the page's language. */
export const lang = () => ctx().lang();
/** True on the pages of a translated language tree. */
export const translated = () => ctx().translated();
/** Absolute address of a file given relative to the site root, from any page: root('assets/data/roadmap.json'). */
export const root = (path) => ctx().root(path);
/** Loads the texts of a translated page once; resolves at once on English/German pages. */
export const load = () => ctx().load();
/** The translation of an English text (after load()), the text itself on English/German pages or if missing. */
export const lookup = (en) => ctx().lookup(en);
/** A {en, de} text (or an English string) in the page's language, with {placeholders} filled. */
export const text = (value, values) => ctx().text(value, values);
/** A {en, de} text as lang spans: both on English/German pages (the switch keeps working), one on the others. */
export const spans = (value, values) => ctx().spans(value, values);
/** A link written for the English/German page, adjusted for this page (untranslated targets lead to the root). */
export const href = (target) => ctx().href(target);
/** BCP 47 locale of the page's language, for Intl. */
export const locale = (l) => ctx().locale(l);
/** A number formatted for the page's language. */
export const number = (value, options) => ctx().number(value, options);
